export const getApplyExcelImportUrl = (id: string, params: ApplyExcelImportParams) => {
  const normalizedParams = new URLSearchParams()

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  })

  const stringifiedParams = normalizedParams.toString()

  return stringifiedParams.length > 0
    ? `/api/v1/approval-cases/${id}/submissions/draft/excel-import/apply?${stringifiedParams}`
    : `/api/v1/approval-cases/${id}/submissions/draft/excel-import/apply`
}

/**
 * @summary Apply selected rows of an Excel form to the draft; the file is attached to the cover sheet element
 */
export const applyExcelImport = async (
  id: string,
  params: ApplyExcelImportParams,
  applyExcelImportBody?: ApplyExcelImportBody,
  headers?: ApplyExcelImportHeaders,
  options?: Parameters<typeof apiFetch>[1],
): Promise<SubmissionDto> => {
  const formData =
    applyExcelImportBody === undefined
      ? undefined
      : (() => {
          const formData = new FormData()
          if (applyExcelImportBody?.file !== undefined) {
            formData.append(`file`, applyExcelImportBody.file)
          }
          if (applyExcelImportBody?.selection !== undefined) {
            formData.append(`selection`, applyExcelImportBody.selection)
          }
          return formData
        })()

  const requestInit: { body?: unknown } & NonNullable<Parameters<typeof apiFetch>[1]> = {
    ...options,
    method: 'POST',
    headers: getHeaders(headers, options?.headers),
  }
  if (formData === undefined) {
    delete requestInit.body
  } else {
    requestInit.body = formData
  }
  return apiFetch<SubmissionDto>(getApplyExcelImportUrl(id, params), requestInit)
}

