export const getPreviewExcelImportUrl = (id: string, params?: PreviewExcelImportParams) => {
  const normalizedParams = new URLSearchParams()

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  })

  const stringifiedParams = normalizedParams.toString()

  return stringifiedParams.length > 0
    ? `/api/v1/approval-cases/${id}/submissions/draft/excel-import/preview?${stringifiedParams}`
    : `/api/v1/approval-cases/${id}/submissions/draft/excel-import/preview`
}

/**
 * @summary Read a filled Excel form (template recognized by its marker cell) against the draft
 */
export const previewExcelImport = async (
  id: string,
  previewExcelImportBody?: PreviewExcelImportBody,
  params?: PreviewExcelImportParams,
  options?: Parameters<typeof apiFetch>[1],
): Promise<FormImportPreviewDto> => {
  const formData =
    previewExcelImportBody === undefined
      ? undefined
      : (() => {
          const formData = new FormData()
          if (previewExcelImportBody?.file !== undefined) {
            formData.append(`file`, previewExcelImportBody.file)
          }
          return formData
        })()

  const requestInit: { body?: unknown } & NonNullable<Parameters<typeof apiFetch>[1]> = {
    ...options,
    method: 'POST',
  }
  if (formData === undefined) {
    delete requestInit.body
  } else {
    requestInit.body = formData
  }
  return apiFetch<FormImportPreviewDto>(getPreviewExcelImportUrl(id, params), requestInit)
}

